    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    class gsl_sf_result_e10(ctypes.Structure):
        _fields_ = [("val", ctypes.c_double), ("err", ctypes.c_double), ("e10", ctypes.c_int)]

    class gsl_sf_result(ctypes.Structure):
        _fields_ = [("val", ctypes.c_double), ("err", ctypes.c_double)]

    gsl.gsl_sf_result_smash_e.argtypes = [ctypes.POINTER(gsl_sf_result_e10), ctypes.POINTER(gsl_sf_result)]
    gsl.gsl_sf_result_smash_e.restype = ctypes.c_int

    input_struct = gsl_sf_result_e10(val=input_dict['val'], err=input_dict['err'], e10=input_dict['e10'])
    output_struct = gsl_sf_result()

    status = gsl.gsl_sf_result_smash_e(ctypes.byref(input_struct), ctypes.byref(output_struct))

    if status != 0:
        raise RuntimeError(f"Error in gsl_sf_result_smash_e: status {status}")

    return {'val': output_struct.val, 'err': output_struct.err}

