import ctypes

# Load the GSL CBLAS library first with RTLD_GLOBAL to avoid symbol resolution issues
cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
# Load the main GSL library next
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

# Define the GSL factor structure
class gsl_factor(ctypes.Structure):
    _fields_ = [
        ("n", ctypes.c_size_t),
        ("p", ctypes.POINTER(ctypes.c_size_t)),
        ("e", ctypes.POINTER(ctypes.c_size_t))
    ]

# Define function signatures
gsl.gsl_factorize.argtypes = [ctypes.c_size_t, ctypes.POINTER(gsl_factor)]
gsl.gsl_factorize.restype = ctypes.c_int

def prime_factors(num):
    if num <= 0:
        raise ValueError("Input number must be a positive integer.")

    factor_struct = gsl_factor()
    result = gsl.gsl_factorize(ctypes.c_size_t(num), ctypes.byref(factor_struct))

    if result != 0:
        raise RuntimeError("Factorization failed.")

    factors = [(factor_struct.p[i], factor_struct.e[i]) for i in range(factor_struct.n)]
    return factors, factor_struct.n

def main():
    try:
        n = int(input("Enter a positive integer to factorize: "))
        factors, count = prime_factors(n)
        print(f"Prime factors of {n}:")
        for prime, exp in factors:
            print(f"{prime}^{exp}")
        print(f"Total number of prime factors: {count}")
    except ValueError as ve:
        print(f"Error: {ve}")
    except RuntimeError as re:
        print(f"Error: {re}")

if __name__ == "__main__":
    main()

