import ctypes

class GSLRng:
    def __init__(self):
        self._init_libs()
        self._define_structures()
        self._define_functions()

    def _init_libs(self):
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    def _define_structures(self):
        class GSLRngState(ctypes.Structure):
            _fields_ = []

        class GSLRngType(ctypes.Structure):
            _fields_ = []

        class GSLRngInstance(ctypes.Structure):
            _fields_ = [
                ("type", ctypes.POINTER(GSLRngType)),
                ("state", ctypes.POINTER(GSLRngState))
            ]

        self.GSLRngInstance = GSLRngInstance

    def _define_functions(self):
        self.libgsl.gsl_rng_ranlxs1_set.argtypes = [ctypes.POINTER(self.GSLRngInstance), ctypes.c_ulong]
        self.libgsl.gsl_rng_ranlxs1_set.restype = None

        self.libgsl.gsl_rng_alloc.argtypes = [ctypes.POINTER(self.GSLRngInstance)]
        self.libgsl.gsl_rng_alloc.restype = ctypes.POINTER(self.GSLRngInstance)

    def initialize_rng(self, seed):
        rng_type = ctypes.c_void_p.in_dll(self.libgsl, "gsl_rng_ranlxs1")
        rng = self.libgsl.gsl_rng_alloc(ctypes.cast(rng_type, ctypes.POINTER(self.GSLRngInstance)))
        if not rng:
            raise RuntimeError("Failed to allocate RNG instance")
        self.libgsl.gsl_rng_ranlxs1_set(rng, ctypes.c_ulong(seed))
        return rng

