class GSLVector:
    def __init__(self, data):
        self.size = len(data)
        self.data = (ctypes.c_double * self.size)(*data)

    def to_list(self):
        return [self.data[i] for i in range(self.size)]

def swap_vectors(vec1, vec2):
    libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    v1 = GSLVector(vec1)
    v2 = GSLVector(vec2)

    gsl.gsl_vector_swap(ctypes.byref(v1), ctypes.byref(v2))

    return v1.to_list(), v2.to_list()

