import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = gsl.gsl_matrix_alloc(rows, cols)

    def __del__(self):
        if self.matrix:
            gsl.gsl_matrix_free(self.matrix)

    @staticmethod
    def numpy_to_gsl(np_array):
        rows, cols = np_array.shape
        gsl_mat = gsl.gsl_matrix_alloc(rows, cols)
        for i in range(rows):
            for j in range(cols):
                gsl.gsl_matrix_set(gsl_mat, i, j, np_array[i, j])
        return gsl_mat

    @staticmethod
    def gsl_to_numpy(gsl_matrix):
        rows = gsl.gsl_matrix_rows(gsl_matrix)
        cols = gsl.gsl_matrix_cols(gsl_matrix)
        np_array = np.zeros((rows, cols))
        for i in range(rows):
            for j in range(cols):
                np_array[i, j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
        return np_array

def gsl_multifit_covar(jacobian, epsrel):
    rows, cols = jacobian.shape
    gsl_jacobian = GSLMatrix.numpy_to_gsl(jacobian)
    covar_gsl = gsl.gsl_matrix_alloc(cols, cols)
    gsl.gsl_multifit_covar(gsl_jacobian, epsrel, covar_gsl)
    covar = GSLMatrix.gsl_to_numpy(covar_gsl)
    gsl.gsl_matrix_free(gsl_jacobian)
    gsl.gsl_matrix_free(covar_gsl)
    return covar

def compute_covariance_matrix(jacobian, epsrel, dim):
    assert isinstance(jacobian, np.ndarray), "Jacobian must be a numpy array"
    assert jacobian.ndim == 2, "Jacobian must be a 2D array"
    assert jacobian.shape[1] == dim, "Jacobian columns must match covariance dimension"
    assert isinstance(epsrel, float) and epsrel >= 0, "Relative error tolerance must be non-negative"
    assert isinstance(dim, int) and dim > 0, "Dimension must be a positive integer"

    try:
        covar = gsl_multifit_covar(jacobian, epsrel)
        return covar
    except Exception as e:
        raise RuntimeError(f"Failed to compute covariance matrix: {e}")

