class GSLSkewnessError(Exception):
    pass

def compute_skewness(data, stride, n):
    if not isinstance(data, np.ndarray) or data.dtype != np.float64:
        raise GSLSkewnessError("Input data must be a NumPy array of dtype float64.")
    if stride < 1:
        raise GSLSkewnessError("Stride must be at least 1.")
    if n < 1:
        raise GSLSkewnessError("Number of elements (n) must be at least 1.")
    if len(data.shape) != 1:
        raise GSLSkewnessError("Data must be a 1D array.")
    if len(data) < (n - 1) * stride + 1:
        raise GSLSkewnessError("Data array is too small for given n and stride.")

    # Load GSL libraries in correct order
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

