    gsl.gsl_stats_skew.argtypes = [
        ctypes.POINTER(ctypes.c_double),
        ctypes.c_size_t,
        ctypes.c_size_t
    ]
    gsl.gsl_stats_skew.restype = ctypes.c_double

    # Call GSL function
    data_ptr = data.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    skew = gsl.gsl_stats_skew(data_ptr, stride, n)
    return skew

