class GSLHistogram:
    def __init__(self, n_bins):
        self.n_bins = n_bins
        self.hist_p = gsl.gsl_histogram_alloc(n_bins)
        if not self.hist_p:
            raise RuntimeError("Failed to allocate histogram")
        # Initialize bins with non-zero values for testing
        for i in range(n_bins):
            gsl.gsl_histogram_set_ranges_uniform(self.hist_p, 0.0, 10.0)
            gsl.gsl_histogram_increment(self.hist_p, i * 0.5)  # Set some values

    def reset(self):
        gsl.gsl_histogram_reset(self.hist_p)

    def all_bins_zero(self):
        for i in range(self.n_bins):
            val = gsl.gsl_histogram_get(self.hist_p, i)
            if val != 0:
                return False
        return True

    def __del__(self):
        if self.hist_p:
            gsl.gsl_histogram_free(self.hist_p)

def create_histogram(n_bins):
    return GSLHistogram(n_bins)

# Main program
if __name__ == "__main__":
    n_bins = 10
    h = create_histogram(n_bins)
    h.reset()
    if h.all_bins_zero():
        print("All bins are reset to zero.")
    else:
        print("Not all bins are zero.")

