class GSLVector:
    def __init__(self, size):
        self._vec = gsl.gsl_vector_alloc(size)

    def __del__(self):
        gsl.gsl_vector_free(self._vec)

    def set(self, i, x):
        gsl.gsl_vector_set(self._vec, i, x)

    def get(self, i):
        return gsl.gsl_vector_get(self._vec, i)

    def size(self):
        return self._vec.contents.size

    def to_list(self):
        return [self.get(i) for i in range(self.size())]

