class GSLVector:
    def __init__(self, size):
        self._vec = gsl.gsl_vector_alloc(size)

    def __del__(self):
        gsl.gsl_vector_free(self._vec)

    def set_value(self, index, value):
        gsl.gsl_vector_set(self._vec, index, value)

    def get_value(self, index):
        return gsl.gsl_vector_get(self._vec, index)

    def set_all(self, values):
        for i, val in enumerate(values):
            self.set_value(i, val)

    def get_all(self, size):
        return [self.get_value(i) for i in range(size)]

def create_and_manipulate_vector(values):
    size = len(values)
    vec = GSLVector(size)
    vec.set_all(values)
    return vec.get_all(size)

