def compute_quadratic_roots(a, b, c):
    if a == 0:
        if b == 0:
            return None  # No solution if both a and b are zero
        root = -c / b
        return (root, root)  # Linear equation case

    # Define argument types for gsl_poly_solve_quadratic
    gsl.gsl_poly_solve_quadratic.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double,
                                            ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_poly_solve_quadratic.restype = ctypes.c_int

    root1 = ctypes.c_double(0)
    root2 = ctypes.c_double(0)

    status = gsl.gsl_poly_solve_quadratic(ctypes.c_double(a), ctypes.c_double(b), ctypes.c_double(c), ctypes.byref(root1), ctypes.byref(root2))

    if status == 0:
        return (root1.value, root2.value)
    elif status == 1:
        return (root1.value, root1.value)  # Equal roots
    else:
        return None  # Complex roots

