def gsl_ldexp_py(x, e):
    # Load libraries in correct order
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define function prototype
    gsl.gsl_ldexp.argtypes = [ctypes.c_double, ctypes.c_int]
    gsl.gsl_ldexp.restype = ctypes.c_double

    # Handle edge cases
    if x == 0.0:
        return 0.0  # x * 2^e is zero if x is zero

    try:
        result = gsl.gsl_ldexp(ctypes.c_double(x), ctypes.c_int(e))
    except OverflowError:
        # Handle overflow (exponent too large)
        return float('inf') if x > 0 else float('-inf')
    except Exception:
        # Handle other potential errors
        return float('nan')

    return result

