def copy_doubles(X, Y, incX, incY):
    if not X or not Y:
        raise ValueError("Input arrays X and Y must not be empty.")
    if len(Y) < len(X):
        raise ValueError("Y must be at least as long as X.")

    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except Exception as e:
        raise RuntimeError("Failed to load GSL libraries.") from e

    n = len(X)
    ptrX = (ctypes.c_double * len(X))(*X)
    ptrY = (ctypes.c_double * len(Y))(*Y)

    gsl.cblas_dcopy(n, ptrX, incX, ptrY, incY)

    for i in range(len(Y)):
        Y[i] = ptrY[i]

