import sys

class GSLRng:
    def __init__(self):
        self.libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        self.rng_type = ctypes.c_void_p()
        self.rng = ctypes.c_void_p()

        # Initialize RNG type and allocate RNG instance
        self.libgsl.gsl_rng_env_setup()
        self.rng_type = self.libgsl.gsl_rng_rand48()
        self.rng = self.libgsl.gsl_rng_alloc(self.rng_type)

    def set_seed(self, seed):
        self.libgsl.gsl_rng_set(self.rng, seed)

    def get_double(self):
        return self.libgsl.gsl_rng_get(self.rng)

    def __del__(self):
        if self.rng:
            self.libgsl.gsl_rng_free(self.rng)

    def generate_random_double(self, seed):
        self.set_seed(seed)
        raw_value = self.get_double()
        max_value = 2**48
        return raw_value / max_value

