class GSLMatrix:
    def __init__(self, rows, cols):
        self._matrix = gsl.gsl_matrix_alloc(rows, cols)

    def __del__(self):
        if self._matrix:
            gsl.gsl_matrix_free(self._matrix)

    def set(self, row, col, value):
        gsl.gsl_matrix_set(self._matrix, row, col, value)

    def get(self, row, col):
        return gsl.gsl_matrix_get(self._matrix, row, col)

    @property
    def ptr(self):
        return self._matrix

def matrix_to_gsl(matrix):
    n = len(matrix)
    gsl_mat = GSLMatrix(n, n)
    for i in range(n):
        for j in range(n):
            gsl_mat.set(i, j, matrix[i][j])
    return gsl_mat

def gsl_matrix_to_numpy(gsl_matrix):
    rows = gsl.gsl_matrix_rows(gsl_matrix.ptr)
    cols = gsl.gsl_matrix_cols(gsl_matrix.ptr)
    result = [[gsl.gsl_matrix_get(gsl_matrix.ptr, i, j) for j in range(cols)] for i in range(rows)]
    return result

def compute_matrix_exponential(matrix, mode):
    n = len(matrix)
    gsl_mat = matrix_to_gsl(matrix)
    exp_mat = GSLMatrix(n, n)

    status = gsl.gsl_linalg_exponential_ss(gsl_mat.ptr, exp_mat.ptr, mode)
    if status != 0:
        raise RuntimeError(f"Error computing matrix exponential, GSL error code {status}")
    return gsl_matrix_to_numpy(exp_mat)

