import ctypes
import numpy as np

class GSLFilterError(Exception):
    pass

def create_gsl_vector(data):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    vec = gsl.gsl_vector_alloc(len(data))
    array_type = ctypes.c_double * len(data)
    gsl.gsl_vector_view_array.return_value = gsl.gsl_vector_view_array(array_type(*data), len(data))
    gsl.gsl_vector_memcpy(vec, gsl.gsl_vector_view_array(array_type(*data), len(data)).vector)
    return vec

def extract_gsl_vector(vec, size):
    data = np.zeros(size, dtype=np.float64)
    for i in range(size):
        data[i] = ctypes.c_double.from_address(vec.contents.data + i * ctypes.sizeof(ctypes.c_double)).value
    return data.tolist()

def gsl_filter_impulse_python(input_data, t, K):
    if not isinstance(input_data, list) or not all(isinstance(x, (int, float)) for x in input_data):
        raise GSLFilterError("Input data must be a list of numbers")
    if not isinstance(t, (int, float)):
        raise GSLFilterError("Threshold t must be a number")
    if not isinstance(K, int) or K <= 0:
        raise GSLFilterError("Workspace size K must be a positive integer")

    n = len(input_data)
    if n < K:
        raise GSLFilterError("Workspace size K cannot exceed input data length")

    libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    workspace = gsl.gsl_filter_impulse_alloc(K)
    if not workspace:
        raise GSLFilterError("Failed to allocate GSL filter workspace")

    try:
        input_vec = create_gsl_vector(input_data)
        output_vec = gsl.gsl_vector_alloc(n)
        outliers = ctypes.c_size_t()

        status = gsl.gsl_filter_impulse(ctypes.c_double(t), input_vec, output_vec, ctypes.byref(outliers), workspace)
        if status != 0:
            raise GSLFilterError(f"GSL error occurred with status code {status}")

        filtered_data = extract_gsl_vector(output_vec, n)
        return filtered_data, outliers.value
    finally:
        gsl.gsl_filter_impulse_free(workspace)
        gsl.gsl_vector_free(input_vec)
        gsl.gsl_vector_free(output_vec)

# Test cases
def run_tests():
    # Valid case
    input_data = [1.0, 2.0, 3.0, 10.0, 2.0, 3.0, 1.0]
    threshold = 3.0
    K = 3
    try:
        filtered_data, outliers = gsl_filter_impulse_python(input_data, threshold, K)
        assert isinstance(filtered_data, list)
        assert isinstance(outliers, int)
        print("Test 1 passed")
    except Exception as e:
        print(f"Test 1 failed: {e}")

    # Invalid input data type
    try:
        gsl_filter_impulse_python("not a list", 3.0, 3)
        assert False, "Test 2 failed: Did not catch invalid input data type"
    except GSLFilterError:
        print("Test 2 passed")

    # Invalid threshold type
    try:
        gsl_filter_impulse_python([1,2,3], "not a number", 3)
        assert False, "Test 3 failed: Did not catch invalid threshold type"
    except GSLFilterError:
        print("Test 3 passed")

    # Invalid K value
    try:
        gsl_filter_impulse_python([1,2,3], 3.0, 0)
        assert False, "Test 4 failed: Did not catch invalid K value"
    except GSLFilterError:
        print("Test 4 passed")

    # K larger than input size
    try:
        gsl_filter_impulse_python([1,2], 3.0, 3)
        assert False, "Test 5 failed: Did not catch K larger than input size"
    except GSLFilterError:
        print("Test 5 passed")

if __name__ == "__main__":
    run_tests()

import ctypes
import sys

def swap_arrays(N, X, incX, Y, incY):
    if not (isinstance(X, list) and isinstance(Y, list)):
        raise TypeError("X and Y must be lists")
    if N <= 0:
        raise ValueError("N must be greater than 0")
    if len(X) < 1 or len(Y) < 1:
        raise ValueError("X and Y must not be empty")

    CDoubleArrayTypeX = ctypes.c_double * len(X)
    c_X = CDoubleArrayTypeX(*X)

    CDoubleArrayTypeY = ctypes.c_double * len(Y)
    c_Y = CDoubleArrayTypeY(*Y)

    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl.cblas_dswap.argtypes = [
        ctypes.c_int,
        ctypes.POINTER(ctypes.c_double),
        ctypes.c_int,
        ctypes.POINTER(ctypes.c_double),
        ctypes.c_int
    ]
    gsl.cblas_dswap.restype = None

    gsl.cblas_dswap(N, c_X, incX, c_Y, incY)

    return list(c_X), list(c_Y)

if __name__ == "__main__":
    try:
        X, Y = swap_arrays(3, [1.0, 2.0, 3.0], 1, [4.0, 5.0, 6.0], 1)
        assert X == [4.0, 5.0, 6.0] and Y == [1.0, 2.0, 3.0], "Test case 1 failed"

        X, Y = swap_arrays(2, [1.0, 2.0, 3.0], 2, [4.0, 5.0, 6.0], 1)
        assert X == [4.0, 2.0, 3.0] and Y == [1.0, 5.0, 6.0], "Test case 2 failed"

        try:
            swap_arrays(0, [1.0, 2.0], 1, [3.0, 4.0], 1)
            assert False, "Test case 3 failed: Expected ValueError for N <= 0"
        except ValueError:
            pass

        try:
            swap_arrays(2, [], 1, [3.0, 4.0], 1)
            assert False, "Test case 4 failed: Expected ValueError for empty X"
        except ValueError:
            pass

        try:
            swap_arrays(2, [1.0, 2.0], 1, [], 1)
            assert False, "Test case 5 failed: Expected ValueError for empty Y"
        except ValueError:
            pass

        try:
            swap_arrays(2, (1.0, 2.0), 1, [3.0, 4.0], 1)
            assert False, "Test case 6 failed: Expected TypeError for non-list X"
        except TypeError:
            pass

        try:
            swap_arrays(2, [1.0, 2.0], 1, (3.0, 4.0), 1)
            assert False, "Test case 7 failed: Expected TypeError for non-list Y"
        except TypeError:
            pass

        print("All test cases passed")
    except Exception as e:
        print(f"An error occurred during testing: {e}")
        sys.exit(1)

