import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.matrix = None

    def _allocate(self):
        if self.matrix is None:
            self.matrix = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_matrix_alloc(self.rows, self.cols)

    def free(self):
        if self.matrix:
            ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_matrix_free(self.matrix)
            self.matrix = None

    def to_numpy(self):
        data = np.ctypeslib.as_array(self.matrix.contents.data, shape=(self.rows, self.cols))
        return data.tolist()

    @staticmethod
    def list_to_ctypes_matrix(lst):
        rows = len(lst)
        cols = len(lst[0]) if rows > 0 else 0
        mat = GSLMatrix(rows, cols)
        mat._allocate()
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        for i in range(rows):
            for j in range(cols):
                gsl.gsl_matrix_set(mat.matrix, i, j, lst[i][j])
        return mat

    @staticmethod
def compute_covariance(jacobian, epsrel):
        gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        n, p = len(jacobian), len(jacobian[0])
        jac = GSLMatrix.list_to_ctypes_matrix(jacobian)
        covar = GSLMatrix(p, p)
        covar._allocate()

        gsl.gsl_multifit_nlinear_covar.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p]
        status = gsl.gsl_multifit_nlinear_covar(jac.matrix, ctypes.c_size_t(p), covar.matrix)

        jac.free()
        result = covar.to_numpy()
        covar.free()

        return result

import ctypes
import numpy as np

class GSLVector:
    def __init__(self, size):
        self._as_parameter_ = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_vector_alloc(size)

    def __del__(self):
        ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_vector_free(self._as_parameter_)

    def set(self, i, value):
        ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_vector_set(self._as_parameter_, i, value)

    def get(self, i):
        return ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_vector_get(self._as_parameter_, i)

    @staticmethod
    def from_array(arr):
        vec = GSLVector(len(arr))
        for i, val in enumerate(arr):
            vec.set(i, val)
        return vec

    def to_array(self, size):
        return np.array([self.get(i) for i in range(size)])

