class GSLFilterImpulseWorkspace:
    def __init__(self, K):
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        self._as_parameter_ = gsl.gsl_filter_impulse_alloc(K)

    def __del__(self):
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_filter_impulse_free(self._as_parameter_)

def generate_noisy_signal(N, outlier_prob=0.05):
    t = np.linspace(0, 4 * np.pi, N)
    signal = np.sin(t)
    noise = np.random.normal(0, 0.1, N)
    noisy_signal = signal + noise

    # Add outliers
    for i in range(N):
        if np.random.rand() < outlier_prob:
            noisy_signal[i] += np.random.choice([-1, 1]) * np.random.uniform(2, 5)

    return noisy_signal

def main(N=100, K=5, t=3.0):
    # Load libraries in correct order
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Generate the noisy signal with outliers
    data = generate_noisy_signal(N)
    x = GSLVector.from_array(data)

    # Allocate workspace and vectors
    work = GSLFilterImpulseWorkspace(K)
    y = GSLVector(N)
    median = GSLVector(N)
    sigma = GSLVector(N)
    outlier = GSLVectorInt(N)

    # Call the GSL impulse filter function
    status = gsl.gsl_filter_impulse(work._as_parameter_, t, x._as_parameter_, y._as_parameter_,
                                    median._as_parameter_, sigma._as_parameter_, outlier._as_parameter_)

    assert status == 0, "Error in GSL impulse filter function"

    # Convert results to numpy arrays
    y_data = y.to_array(N)
    median_data = median.to_array(N)
    sigma_data = sigma.to_array(N)
    outlier_data = outlier.to_array(N)

    # Print the filtered signal and related statistics
    for i in range(N):
        print(f"Data point {i}: Original = {data[i]:.4f}, Filtered = {y_data[i]:.4f}, "
              f"Median = {median_data[i]:.4f}, Sigma = {sigma_data[i]:.4f}, "
              f"Outlier: {'Yes' if outlier_data[i] else 'No'}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 4:
        print("Usage: python impulse_filter.py <N> <K> <t>")
        print("Using default values: N=100, K=5, t=3.0")
        main()
    else:
        N = int(sys.argv[1])
        K = int(sys.argv[2])
        t = float(sys.argv[3])
        main(N, K, t)

