import ctypes

class GSLCombination:
    def __init__(self, n, k):
        self.n = n
        self.k = k
        self.comb = ctypes.create_string_buffer(ctypes.sizeof(ctypes.c_int) * (k + 1))
        self._init_combination()

    def _init_combination(self):
        comb_type = ctypes.c_int * self.k
        comb_array = comb_type(*range(self.k))
        ctypes.memmove(self.comb, comb_array, ctypes.sizeof(comb_array))

    def data(self):
        return ctypes.cast(self.comb, ctypes.POINTER(ctypes.c_int))


def next_combination(current_combination, n):
    libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    k = len(current_combination)
    if k == 0 or current_combination[-1] >= n - 1:
        return None

    # Initialize combination structure
    c = GSLCombination(n, k)
    comb_data = c.data()

    # Copy current combination into the GSLCombination structure
    for i, val in enumerate(current_combination):
        comb_data[i] = ctypes.c_int(val)

    # Call GSL function
    result = gsl.gsl_combination_next(comb_data, n, k)

    if result == 0:
        next_comb = tuple(comb_data[i] for i in range(k))
        return next_comb
    else:
        return None

