def create_histogram2d(nx, ny, xrange, yrange):
    if not isinstance(nx, int) or nx <= 0:
        raise ValueError('nx must be a positive integer')
    if not isinstance(ny, int) or ny <= 0:
        raise ValueError('ny must be a positive integer')
    if not all(isinstance(x, (int, float)) for x in xrange):
        raise ValueError('xrange must contain only numeric values')
    if not all(isinstance(y, (int, float)) for y in yrange):
        raise ValueError('yrange must contain only numeric values')
    if any(xrange[i] >= xrange[i+1] for i in range(len(xrange)-1)):
        raise ValueError('xrange must be in increasing order')
    if any(yrange[i] >= yrange[i+1] for i in range(len(yrange)-1)):
        raise ValueError('yrange must be in increasing order')

    libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    GSL_Histogram2D = ctypes.c_void_p

    gsl.gsl_histogram2d_calloc_range.argtypes = [ctypes.c_size_t, ctypes.c_size_t, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_histogram2d_calloc_range.restype = ctypes.POINTER(GSL_Histogram2D)

    xr = (ctypes.c_double * len(xrange))(*xrange)
    yr = (ctypes.c_double * len(yrange))(*yrange)

    hist_ptr = gsl.gsl_histogram2d_calloc_range(nx, ny, xr, yr)
