import ctypes
import numpy as np

# Load libraries in the correct order
cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def validate_vectors(vector_x, vector_y):
    if not isinstance(vector_x, (list, np.ndarray)) or not isinstance(vector_y, (list, np.ndarray)):
        raise ValueError("Both vectors must be a list or numpy array.")
    if len(vector_x) != len(vector_y):
        raise ValueError("Vectors must be of the same length.")
    if not all(isinstance(x, (int, float)) for x in vector_x) or not all(isinstance(y, (int, float)) for y in vector_y):
        raise ValueError("All elements must be of type float or int.")

def dot_product(vector_x, vector_y):
    validate_vectors(vector_x, vector_y)

    n = len(vector_x)
    x = (ctypes.c_double * n)(*vector_x)
    y = (ctypes.c_double * n)(*vector_y)

    gsl.gsl_set_error_handler_off()
    result = cblas.cblas_ddot(ctypes.c_int(n), ctypes.cast(x, ctypes.POINTER(ctypes.c_double)), ctypes.c_int(1), ctypes.cast(y, ctypes.POINTER(ctypes.c_double)), ctypes.c_int(1))
    return result

# Test cases
def test_dot_product():
    assert dot_product([1, 2, 3], [4, 5, 6]) == 32.0
    assert dot_product([0, 0], [0, 0]) == 0.0
    assert dot_product([1.5, 2.5], [2.0, 4.0]) == 13.0
    try:
        dot_product([1, 2], [1])
    except ValueError as e:
        assert str(e) == "Vectors must be of the same length."
    try:
        dot_product([1, 'a'], [2, 3])
    except ValueError as e:
        assert str(e) == "All elements must be of type float or int."
    print("All tests passed!")

if __name__ == "__main__":
    test_dot_product()

