class GslRstatQuantileWorkspace:
    def __init__(self, p):
        self._workspace = None
        self._lib = None
        self._init_lib()
        if not (0.0 <= p <= 1.0):
            raise ValueError("Quantile p must be between 0 and 1.")
        self.p = p
        self._alloc(p)

