        try:
            ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            self._lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        except OSError as e:
            raise RuntimeError("Failed to load GSL libraries.") from e

        # Define function signatures
        self._lib.gsl_rstat_quantile_alloc.argtypes = [ctypes.c_double]
        self._lib.gsl_rstat_quantile_alloc.restype = ctypes.POINTER(ctypes.c_void_p)

        self._lib.gsl_rstat_quantile_reset.argtypes = [ctypes.POINTER(ctypes.c_void_p)]
        self._lib.gsl_rstat_quantile_reset.restype = None

        self._lib.gsl_rstat_quantile_add.argtypes = [ctypes.c_double, ctypes.POINTER(ctypes.c_void_p)]
        self._lib.gsl_rstat_quantile_add.restype = None

        self._lib.gsl_rstat_quantile_get.argtypes = [ctypes.POINTER(ctypes.c_void_p)]
        self._lib.gsl_rstat_quantile_get.restype = ctypes.c_double

        self._lib.gsl_rstat_quantile_free.argtypes = [ctypes.POINTER(ctypes.c_void_p)]
        self._lib.gsl_rstat_quantile_free.restype = None

    def _alloc(self, p):
        self._workspace = self._lib.gsl_rstat_quantile_alloc(p)
        if not self._workspace:
            raise MemoryError("Failed to allocate GSL quantile workspace.")

    def reset(self):
        if self._workspace:
            self._lib.gsl_rstat_quantile_reset(self._workspace)

    def add_value(self, value):
        if not self._workspace:
            raise RuntimeError("Workspace not allocated.")
        self._lib.gsl_rstat_quantile_add(ctypes.c_double(value), self._workspace)

    def get_quantile(self):
        if not self._workspace:
            raise RuntimeError("Workspace not allocated.")
        return self._lib.gsl_rstat_quantile_get(self._workspace)

    def free(self):
        if self._workspace:
            self._lib.gsl_rstat_quantile_free(self._workspace)
            self._workspace = None

    def __del__(self):
        self.free()

