import ctypes

def daxpy(N, alpha, X, Y):
    if not (isinstance(N, int) and isinstance(alpha, (int, float)) and isinstance(X, list) and isinstance(Y, list)):
        raise TypeError("Invalid input types")
    if N <= 0:
        raise ValueError("N must be greater than 0")
    if len(X) < N or len(Y) < N:
        raise ValueError("Input lists X and Y must be at least of length N")

    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError("Failed to load GSL libraries") from e

    cblas_daxpy = gsl.cblas_daxpy
    cblas_daxpy.argtypes = [ctypes.c_int, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int]
    cblas_daxpy.restype = None

    X_arr = (ctypes.c_double * N)(*X)
    Y_arr = (ctypes.c_double * N)(*Y)

    cblas_daxpy(N, alpha, X_arr, 1, Y_arr, 1)

    return list(Y_arr)

